CREATE DATABASE IF NOT EXISTS powerbank CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE powerbank;
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40),password VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'CUSTOMER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS station(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),address VARCHAR(255),latitude DOUBLE,longitude DOUBLE,capacity INT,status VARCHAR(30),opening_hours VARCHAR(80));
CREATE TABLE IF NOT EXISTS powerbanks(id BIGINT AUTO_INCREMENT PRIMARY KEY,serial_number VARCHAR(100),status VARCHAR(30),battery_level INT,station_id BIGINT,FOREIGN KEY(station_id) REFERENCES station(id));
CREATE TABLE IF NOT EXISTS reservation(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,station_id BIGINT,power_bank_id BIGINT,pickup_code VARCHAR(20),status VARCHAR(30),created_at TIMESTAMP,expires_at TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(station_id) REFERENCES station(id),FOREIGN KEY(power_bank_id) REFERENCES powerbanks(id));
CREATE TABLE IF NOT EXISTS rental(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,power_bank_id BIGINT,reservation_id BIGINT,start_time TIMESTAMP,end_time TIMESTAMP,status VARCHAR(30),hourly_rate_snapshot DOUBLE,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(power_bank_id) REFERENCES powerbanks(id),FOREIGN KEY(reservation_id) REFERENCES reservation(id));
CREATE TABLE IF NOT EXISTS return_record(id BIGINT AUTO_INCREMENT PRIMARY KEY,rental_id BIGINT,return_station_id BIGINT,returned_at TIMESTAMP,final_cost DOUBLE,inspection_status VARCHAR(40),FOREIGN KEY(rental_id) REFERENCES rental(id),FOREIGN KEY(return_station_id) REFERENCES station(id));
CREATE TABLE IF NOT EXISTS maintenance_request(id BIGINT AUTO_INCREMENT PRIMARY KEY,target_type VARCHAR(40),target_id BIGINT,description TEXT,priority VARCHAR(30),status VARCHAR(30),created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor VARCHAR(120),action VARCHAR(120),details TEXT,created_at TIMESTAMP);
